120	.hero h1 em{
121	  font-style:normal;color:var(--accent-2);
122	  background:linear-gradient(transparent 65%,rgba(224,122,60,.32) 65%);
123	  padding:0 6px;
124	}
125	.hero-sub{
126	  font-size:22px;color:var(--ink);font-weight:700;line-height:1.55;
127	  margin:0 0 14px;
128	}
129	.hero-trust{
130	  font-size:14px;color:var(--ink-soft);letter-spacing:.06em;font-weight:600;
131	  padding-top:18px;margin-top:18px;border-top:1px dashed var(--line-mid);
132	  display:flex;flex-wrap:wrap;gap:6px 22px;align-items:center;
133	}
134	.hero-trust b{color:var(--deep-2);font-weight:900}
135	.hero-cta-row{
136	  display:flex;gap:14px;flex-wrap:wrap;margin-top:32px;
137	}
138	.btn-hero-primary{
139	  display:inline-flex;align-items:center;gap:10px;
140	  padding:18px 32px;border-radius:999px;
141	  background:linear-gradient(135deg,var(--accent),var(--accent-2));
142	  color:#fff;font-size:16px;font-weight:900;letter-spacing:.04em;
143	  border:0;cursor:pointer;font-family:inherit;
144	  box-shadow:0 16px 32px -12px rgba(224,122,60,.55);
145	  transition:.22s;
146	}
147	.btn-hero-primary:hover{transform:translateY(-2px);box-shadow:0 20px 38px -12px rgba(224,122,60,.7)}
148	.btn-hero-ghost{
149	  display:inline-flex;align-items:center;gap:10px;
150	  padding:18px 28px;border-radius:999px;
151	  background:transparent;border:1.5px solid var(--deep);
152	  color:var(--deep);font-size:15px;font-weight:700;
153	  cursor:pointer;font-family:inherit;transition:.22s;
154	}
155	.btn-hero-ghost:hover{background:var(--deep);color:#fff}
156	.hero-manifesto{
157	  margin-top:32px;padding:22px 26px;
158	  background:#fff;border:1px solid var(--accent-soft);
159	  border-left:4px solid var(--accent);
160	  border-radius:0 14px 14px 0;
161	  max-width:600px;
162	  box-shadow:0 14px 30px -16px rgba(15,42,38,.22);
163	}
164	.hero-manifesto p{
165	  margin:0;font-size:15.5px;color:var(--ink);
166	  line-height:1.85;font-style:italic;
167	}
168	.hero-manifesto p b{color:var(--accent-2);font-weight:900;font-style:normal}
169	.hero-manifesto span{
170	  display:inline-block;font-size:12px;color:var(--accent-2);
171	  font-weight:800;letter-spacing:.14em;margin-top:10px;
172	}
173	.hero-tagline{
174	  margin-top:36px;font-size:11.5px;letter-spacing:.36em;color:var(--ink-faint);font-weight:700;
175	}
176	.hero-portrait{
177	  position:relative;border-radius:18px;overflow:hidden;
178	  box-shadow:0 30px 70px -25px rgba(15,42,38,.45);
179	  aspect-ratio:4/5;
180	}
181	.hero-portrait img{width:100%;height:100%;object-fit:cover;object-position:center top}
182	.hero-portrait .badge{
183	  position:absolute;left:18px;bottom:18px;
184	  background:rgba(15,42,38,.92);color:var(--paper);
185	  padding:10px 18px;border-radius:10px;
186	  font-size:12px;font-weight:700;letter-spacing:.05em;
187	  backdrop-filter:blur(8px);
188	}
189	.hero-portrait .badge .name{font-family:"Noto Serif TC",serif;font-weight:900;font-size:17px;color:#fff;margin-bottom:2px}
190	@media (max-width:900px){
191	  .hero-grid{grid-template-columns:1fr;gap:36px}
192	  .hero h1{font-size:44px}
193	  .hero-sub{font-size:18px}
194	}
195	
196	/* ===== 認知翻轉 ===== */
197	.shift{background:var(--paper-3);border-top:1px solid var(--line-soft);border-bottom:1px solid var(--line-soft)}
198	.phil-quote{
199	  background:#fff;border-left:5px solid var(--accent);
200	  padding:22px 28px;margin:28px 0 36px;
201	  border-radius:0 12px 12px 0;
202	  box-shadow:0 10px 30px -18px rgba(15,42,38,.25);
203	}
204	.phil-quote .q{font-size:16.5px;color:var(--deep-2);line-height:1.85;font-style:italic;margin:0}
205	.phil-quote .src{font-size:12.5px;color:var(--accent-2);font-weight:800;letter-spacing:.08em;margin-top:10px;display:block}
206	.compare{
207	  display:grid;grid-template-columns:1fr 1fr;gap:0;
208	  border:1px solid var(--line-soft);border-radius:14px;overflow:hidden;background:#fff;
209	}
210	.compare-col{padding:32px 28px}
211	.compare-col.lose{background:linear-gradient(180deg,#fcf4f0,#fff)}
212	.compare-col.win{background:linear-gradient(180deg,#f0f6f1,#fff);border-left:1px solid var(--line-soft)}
213	.compare-col h4{
214	  font-family:"Noto Serif TC",serif;font-weight:900;font-size:20px;margin:0 0 18px;
215	  display:flex;align-items:center;gap:10px;
216	}
217	.compare-col.lose h4{color:var(--red-soft)}
218	.compare-col.win h4{color:var(--green-good)}
219	.compare-col h4 .ico{width:32px;height:32px;border-radius:50%;display:grid;place-items:center;color:#fff;font-size:13px;font-weight:900;flex-shrink:0}
220	.compare-col.lose h4 .ico{background:var(--red-soft)}
221	.compare-col.win h4 .ico{background:var(--green-good)}
222	.compare-col ul{margin:0;padding:0;list-style:none}
223	.compare-col li{
224	  font-size:14.5px;line-height:1.75;padding:10px 0;
225	  border-top:1px dashed var(--line-soft);
226	  color:var(--ink);
227	}
228	.compare-col li:first-child{border-top:0}
229	@media (max-width:820px){
230	  .compare{grid-template-columns:1fr}
231	  .compare-col.win{border-left:0;border-top:1px solid var(--line-soft)}
232	}
233	
234	/* ===== Why Coach ===== */
235	.why-grid{display:grid;grid-template-columns:1.2fr 1fr;gap:60px;align-items:start}
236	.why-stats{
237	  display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:24px 0 32px;
238	}
239	.why-stat{
240	  background:#fff;border:1px solid var(--line-soft);border-radius:12px;
241	  padding:18px 20px;
242	}
243	.why-stat .n{
244	  font-family:"Noto Serif TC",serif;font-weight:900;font-size:30px;
245	  color:var(--accent-2);line-height:1;
246	}
247	.why-stat .l{font-size:13px;color:var(--ink-soft);font-weight:600;margin-top:6px;letter-spacing:.04em}
248	.traits{display:flex;flex-direction:column;gap:18px;margin-top:8px}
249	.trait{
250	  display:flex;gap:18px;background:#fff;border:1px solid var(--line-soft);
251	  border-radius:14px;padding:20px 22px;
252	}
253	.trait .ch{
254	  flex-shrink:0;width:54px;height:54px;border-radius:14px;
255	  background:linear-gradient(135deg,var(--deep),var(--deep-2));
256	  color:var(--paper);display:grid;place-items:center;
257	  font-family:"Noto Serif TC",serif;font-weight:900;font-size:26px;
258	}
259	.trait h4{font-family:"Noto Serif TC",serif;font-weight:900;font-size:18px;color:var(--deep-2);margin:0 0 6px}
260	.trait p{margin:0;font-size:14.5px;color:var(--ink-soft);line-height:1.7}
261	@media (max-width:820px){
262	  .why-grid{grid-template-columns:1fr;gap:36px}
263	}
264	
265	/* ===== 海餅乾正典 ===== */
266	.canon{background:linear-gradient(180deg,var(--deep) 0%,var(--deep-2) 100%);color:var(--paper);position:relative}
267	.canon::before{
268	  content:'';position:absolute;inset:0;
269	  background:
270	    radial-gradient(500px 280px at 100% 0%,rgba(224,122,60,.22),transparent 60%),
271	    radial-gradient(400px 220px at 0% 100%,rgba(181,138,79,.18),transparent 60%);
272	  pointer-events:none;
273	}
274	.canon .wrap{position:relative;z-index:1;max-width:880px;text-align:center}
275	.canon .eyebrow{color:var(--accent-soft)}
276	.canon .sec-title{color:#fff}
277	.canon .sec-title-underline{margin-left:auto;margin-right:auto}
278	.canon-mission{
279	  margin:18px auto 50px;font-family:"Noto Serif TC",serif;font-weight:900;
280	  font-size:30px;line-height:2;color:#fff;
281	}
282	.canon-mission em{font-style:normal;background:linear-gradient(transparent 65%,rgba(224,122,60,.42) 65%);padding:0 8px}
283	.canon-divider{width:80px;height:1px;background:rgba(255,255,255,.3);margin:36px auto}
284	.canon-beliefs-title{font-family:"Noto Serif TC",serif;font-weight:900;font-size:24px;margin-bottom:32px;letter-spacing:.06em}
285	.canon-beliefs{display:flex;flex-direction:column;gap:24px;text-align:left;max-width:680px;margin:0 auto}
286	.canon-belief{
287	  display:flex;gap:20px;align-items:flex-start;
288	  background:rgba(255,255,255,.05);
289	  border:1px solid rgba(255,255,255,.12);
290	  border-radius:16px;padding:22px 26px;
291	  backdrop-filter:blur(8px);
292	}
293	.canon-belief .num{
294	  flex-shrink:0;width:44px;height:44px;border-radius:50%;
295	  background:linear-gradient(135deg,var(--accent),var(--accent-2));
296	  color:#fff;display:grid;place-items:center;
297	  font-family:"Noto Serif TC",serif;font-weight:900;font-size:18px;
298	}
299	.canon-belief p{margin:0;font-size:16px;line-height:1.85;color:#fff}
300	.canon-belief b{color:var(--accent-soft);font-weight:900}
301	.canon-footnote{
302	  margin-top:42px;font-size:11px;letter-spacing:.24em;
303	  color:rgba(255,255,255,.5);font-weight:700;
304	}
305	
306	/* ===== 六大器材 ===== */
307	.equipment{background:var(--paper)}
308	.eq-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:22px;margin-top:8px}
309	.eq-card{
310	  background:#fff;border:1px solid var(--line-soft);border-radius:18px;
311	  padding:28px 24px;display:flex;flex-direction:column;
312	  transition:.25s;position:relative;overflow:hidden;
313	}
314	.eq-card::before{
315	  content:'';position:absolute;left:0;top:0;width:100%;height:4px;
316	  background:linear-gradient(90deg,var(--accent),var(--accent-2));
317	  transform:scaleX(0);transform-origin:left;transition:.4s;
318	}
319	.eq-card:hover{transform:translateY(-4px);box-shadow:0 20px 40px -20px rgba(15,42,38,.25)}
320	.eq-card:hover::before{transform:scaleX(1)}
321	.eq-head{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:18px}
322	.eq-icon{
323	  width:54px;height:54px;border-radius:14px;
324	  background:linear-gradient(135deg,var(--deep),var(--deep-2));
325	  color:var(--accent-soft);display:grid;place-items:center;font-size:24px;
326	}
327	.eq-badge{
328	  font-size:10.5px;font-weight:800;letter-spacing:.12em;
329	  background:var(--accent-soft);color:var(--accent-2);
330	  padding:4px 10px;border-radius:6px;
331	}
332	.eq-card h3{font-family:"Noto Serif TC",serif;font-weight:900;font-size:22px;color:var(--deep-2);margin:0 0 6px}
333	.eq-card .obj{font-size:13.5px;color:var(--accent-2);font-weight:800;margin:0 0 14px;letter-spacing:.02em}
334	.eq-card .body{font-size:14px;color:var(--ink-soft);line-height:1.75;flex:1;margin:0 0 16px}
335	.eq-card .body b{color:var(--deep-2);font-weight:900}
336	.eq-card .outcome{
337	  padding-top:14px;border-top:1px dashed var(--line-soft);
338	  font-size:12.5px;color:var(--ink-soft);
339	}
340	.eq-card .outcome b{color:var(--green-good);font-weight:900}
341	@media (max-width:920px){.eq-grid{grid-template-columns:repeat(2,1fr)}}
342	@media (max-width:600px){.eq-grid{grid-template-columns:1fr}}
343	.eq-tagline{
344	  margin-top:36px;text-align:center;
345	  background:#fff;border:1px dashed var(--accent);border-radius:14px;
346	  padding:18px 24px;display:inline-flex;align-items:center;gap:12px;
347	}
348	.eq-tagline i{color:var(--accent)}
349	.eq-tagline .text{font-family:"Noto Serif TC",serif;font-weight:900;font-size:16.5px;color:var(--deep-2)}
350	.eq-tagline-row{text-align:center;margin-top:36px}
351	
352	/* ===== 卡牌 / 4 步驟 ===== */
353	.accountable{background:linear-gradient(180deg,var(--paper-3),var(--paper-2));border-top:1px solid var(--line-soft);border-bottom:1px solid var(--line-soft)}
354	.accountable .wrap{max-width:1100px}
355	.formula{
356	  display:grid;grid-template-columns:repeat(4,1fr);gap:18px;margin-bottom:50px;
357	}
358	.step{
359	  background:#fff;border:1px solid var(--line-soft);border-radius:16px;
360	  padding:24px 22px;position:relative;
361	}
362	.step.consequence{background:linear-gradient(180deg,#fff7f0,#fff);border-color:var(--accent-soft)}
363	.step .num{
364	  font-family:"Noto Serif TC",serif;font-weight:900;font-size:13px;
365	  color:var(--accent-2);letter-spacing:.2em;margin-bottom:8px;
366	}
367	.step h4{font-family:"Noto Serif TC",serif;font-weight:900;font-size:22px;color:var(--deep-2);margin:0 0 8px}
368	.step p{font-size:13.5px;color:var(--ink-soft);line-height:1.7;margin:0}
369	@media (max-width:900px){.formula{grid-template-columns:1fr 1fr}}
370	@media (max-width:500px){.formula{grid-template-columns:1fr}}
371	.scoreboard{
372	  background:#fff;border:1px solid var(--line-soft);border-radius:18px;
373	  padding:36px;display:grid;grid-template-columns:1fr 1fr;gap:36px;
374	}
375	.scoreboard h3{font-family:"Noto Serif TC",serif;font-weight:900;font-size:26px;color:var(--deep-2);margin:0 0 14px}
376	.scoreboard p{font-size:14.5px;color:var(--ink-soft);line-height:1.8;margin:0 0 18px}
377	.scoreboard ul{margin:0;padding:0;list-style:none}
378	.scoreboard li{
379	  font-size:13.5px;color:var(--ink);
380	  padding:8px 0 8px 28px;position:relative;
381	}
382	.scoreboard li::before{
383	  content:'\f00c';font-family:'Font Awesome 6 Free';font-weight:900;
384	  position:absolute;left:0;top:8px;color:var(--green-good);font-size:12px;
385	}
386	.improve{
387	  background:linear-gradient(135deg,#fff8f0,#fcebd9);
388	  border:1.5px dashed var(--accent);border-radius:14px;
389	  padding:24px 28px;display:flex;gap:18px;align-items:flex-start;
390	}
391	.improve .ico{
392	  flex-shrink:0;width:48px;height:48px;border-radius:12px;
393	  background:linear-gradient(135deg,var(--accent),var(--accent-2));
394	  color:#fff;display:grid;place-items:center;font-size:22px;
395	}
396	.improve h4{font-family:"Noto Serif TC",serif;font-weight:900;font-size:20px;color:var(--deep-2);margin:0 0 6px}
397	.improve p{font-size:14.5px;color:var(--ink-soft);line-height:1.75;margin:0}
398	@media (max-width:820px){.scoreboard{grid-template-columns:1fr;padding:28px}}
399	
400	/* ===== 下次見面 ===== */
401	.next-meet{background:var(--paper);text-align:center}
402	.next-meet .wrap{max-width:780px}
403	.next-card{
404	  background:linear-gradient(135deg,var(--deep),var(--deep-2));
405	  color:#fff;border-radius:20px;padding:48px 36px;
406	  box-shadow:0 30px 70px -25px rgba(15,42,38,.45);position:relative;overflow:hidden;
407	}
408	.next-card::before{
409	  content:'';position:absolute;top:-100px;right:-80px;width:300px;height:300px;
410	  border-radius:50%;background:radial-gradient(circle,rgba(224,122,60,.25),transparent 70%);
411	}
412	.next-card-inner{position:relative;z-index:1}
413	.next-tag{
414	  display:inline-block;font-size:11px;letter-spacing:.32em;font-weight:800;
415	  color:var(--accent-soft);background:rgba(255,255,255,.08);
416	  padding:6px 16px;border-radius:999px;border:1px solid rgba(255,255,255,.15);margin-bottom:18px;
417	}
418	.next-card h3{font-family:"Noto Serif TC",serif;font-weight:900;font-size:32px;color:#fff;margin:0 0 12px;line-height:1.4}
419	.next-card p{font-size:16px;color:rgba(255,255,255,.85);max-width:520px;margin:0 auto 28px;line-height:1.85}
420	.next-line-cta{
421	  display:inline-flex;align-items:center;gap:12px;
422	  background:var(--line-green);color:#fff;
423	  padding:16px 32px;border-radius:999px;font-weight:900;font-size:15px;
424	  transition:.22s;
425	}
426	.next-line-cta:hover{transform:translateY(-2px);background:#04a847}
427	
428	/* ===== FAQ ===== */
429	.faq{background:var(--paper-3);border-top:1px solid var(--line-soft)}
430	.faq-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:14px}
431	.faq-item{
432	  background:#fff;border:1px solid var(--line-soft);border-radius:14px;
433	  padding:24px 26px;
434	}
435	.faq-item .q{
436	  display:flex;gap:12px;align-items:flex-start;
437	  font-family:"Noto Serif TC",serif;font-weight:900;font-size:17px;color:var(--deep-2);margin-bottom:10px;
438	}
439	.faq-item .q .mark{
440	  flex-shrink:0;width:28px;height:28px;border-radius:50%;
441	  background:var(--accent-soft);color:var(--accent-2);
442	  display:grid;place-items:center;font-size:12px;font-weight:900;
443	}
444	.faq-item .a{font-size:14.5px;color:var(--ink-soft);line-height:1.8;margin:0;padding-left:40px}
445	@media (max-width:820px){.faq-grid{grid-template-columns:1fr}.faq-item .a{padding-left:0}}
446	
447	/* ===== 90 分鐘 CTA ===== */
448	.cta90{background:linear-gradient(135deg,var(--deep-2),#0a1f1c);color:#fff;position:relative;overflow:hidden}
449	.cta90::before{
450	  content:'';position:absolute;inset:0;
451	  background:
452	    radial-gradient(700px 380px at 100% 0%,rgba(224,122,60,.18),transparent 60%),
453	    radial-gradient(500px 280px at 0% 100%,rgba(181,138,79,.12),transparent 60%);
454	  pointer-events:none;
455	}
456	.cta90 .wrap{position:relative;z-index:1;max-width:880px;text-align:center}
457	.cta90 .eyebrow{color:var(--accent-soft)}
458	.cta90 h2{
459	  font-family:"Noto Serif TC",serif;font-weight:900;
460	  font-size:48px;color:#fff;margin:0 0 18px;line-height:1.3;
461	}
462	.cta90 h2 em{font-style:normal;color:var(--accent);background:linear-gradient(transparent 65%,rgba(224,122,60,.32) 65%);padding:0 6px}
463	.cta90-sub{font-size:19px;color:rgba(255,255,255,.85);max-width:640px;margin:0 auto 28px;line-height:1.8}
464	.cta90-sub b{color:var(--accent-soft);font-weight:900}
465	.cta90-quote{
466	  background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.12);
467	  border-radius:18px;padding:28px 32px;margin:32px auto;max-width:680px;
468	  text-align:left;backdrop-filter:blur(8px);
469	}
470	.cta90-quote .label{font-size:11px;letter-spacing:.32em;color:var(--accent-soft);font-weight:800;margin-bottom:12px}
471	.cta90-quote .q{font-size:17px;line-height:1.85;color:#fff;margin:0;font-style:italic}
472	.cta90-actions{display:flex;gap:14px;justify-content:center;flex-wrap:wrap;margin-top:32px}
473	.btn-cta90{
474	  display:inline-flex;align-items:center;gap:10px;
475	  padding:18px 36px;border-radius:999px;
476	  background:linear-gradient(135deg,var(--accent),var(--accent-2));
477	  color:#fff;font-size:16px;font-weight:900;letter-spacing:.04em;
478	  border:0;cursor:pointer;font-family:inherit;
479	  box-shadow:0 20px 40px -16px rgba(224,122,60,.6);
480	  transition:.22s;
481	}
482	.btn-cta90:hover{transform:translateY(-2px);box-shadow:0 24px 48px -16px rgba(224,122,60,.75)}
483	.btn-cta90-ghost{
484	  display:inline-flex;align-items:center;gap:10px;
485	  padding:18px 32px;border-radius:999px;
486	  background:transparent;border:1.5px solid rgba(255,255,255,.4);
487	  color:#fff;font-size:15px;font-weight:700;
488	  transition:.22s;
489	}
490	.btn-cta90-ghost:hover{background:rgba(255,255,255,.1)}
491	.cta90-promise{
492	  margin-top:32px;font-size:13px;letter-spacing:.18em;color:rgba(255,255,255,.5);font-weight:700;
493	}
494	
495	/* ===== 結語 ===== */
496	.bookend{background:var(--paper);padding:50px 24px;text-align:center;border-top:1px solid var(--line-soft)}
497	.bookend .q{font-family:"Noto Serif TC",serif;font-weight:900;font-size:22px;color:var(--deep-2);margin:0 0 8px}
498	.bookend .src{font-size:12px;color:var(--ink-faint);letter-spacing:.12em;font-weight:700;margin-bottom:24px}
499	.bookend .meta{font-size:12.5px;color:var(--ink-soft);max-width:480px;margin:0 auto;line-height:1.8}
500	
501	/* ===== FOOTER ===== */
502	.foot{background:var(--deep-2);color:rgba(250,246,238,.7);padding:32px 24px;text-align:center;font-size:12.5px;line-height:1.85}
503	.foot b{color:#fff;font-weight:800}
504	.foot .row{margin-bottom:4px}
505	.foot a{color:var(--accent-soft)}
506	
507	/* ===== Modal (照抄 EDM 機制) ===== */
508	.modal{position:fixed;inset:0;z-index:200;display:none;align-items:center;justify-content:center;padding:16px}
509	.modal.show{display:flex}
510	.modal-bg{position:absolute;inset:0;background:rgba(0,0,0,.65);backdrop-filter:blur(8px)}
511	.modal-box{position:relative;background:#fff;border-radius:20px;width:100%;max-width:480px;overflow:hidden;box-shadow:0 28px 60px -20px rgba(0,0,0,.45);animation:modalIn .25s ease;max-height:92vh;overflow-y:auto}
512	@keyframes modalIn{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}
513	.modal-head{background:linear-gradient(135deg,var(--deep),var(--deep-2));color:#fff;padding:22px 26px;display:flex;justify-content:space-between;align-items:flex-start;gap:12px}
514	.modal-title{font-weight:900;font-size:21px;font-family:"Noto Serif TC",serif;line-height:1.3}
515	.modal-sub{font-size:13px;color:var(--accent-soft);margin-top:4px}
516	.modal-close{background:transparent;border:0;color:rgba(255,255,255,.75);font-size:30px;line-height:1;cursor:pointer;padding:0;flex-shrink:0}
517	.modal-close:hover{color:#fff}
518	.modal-body{padding:24px 26px 28px}
519	.field{display:block;margin-bottom:14px}
520	.field label{display:block;font-size:11.5px;font-weight:800;letter-spacing:.18em;color:var(--ink-soft);margin-bottom:6px}
521	.field input,.field textarea{width:100%;border:1px solid var(--line-soft);border-radius:10px;padding:11px 14px;font-size:15px;font-family:inherit;outline:none;transition:.2s;background:var(--paper);box-sizing:border-box;resize:none}
522	.field input:focus,.field textarea:focus{border-color:var(--accent);box-shadow:0 0 0 3px rgba(224,122,60,.18);background:#fff}
523	.field-row{display:grid;grid-template-columns:1fr 1fr;gap:12px}
524	.field-check{display:flex;gap:10px;align-items:flex-start;margin-top:10px;font-size:13.5px;color:var(--ink-soft);line-height:1.55}
525	.field-check input{width:16px;height:16px;margin-top:3px;accent-color:var(--accent);flex-shrink:0}
526	.modal-actions{display:flex;gap:10px;margin-top:22px}
527	.btn-ghost{flex:1;height:48px;border:1px solid var(--line-soft);background:#fff;color:var(--ink);font-weight:700;border-radius:999px;font-size:15px;cursor:pointer;transition:.2s;font-family:inherit}
528	.btn-ghost:hover{background:var(--paper-2)}
529	.btn-submit{flex:1;height:48px;background:linear-gradient(135deg,var(--accent),var(--accent-2));color:#fff;font-weight:900;border:0;border-radius:999px;font-size:15px;cursor:pointer;transition:.2s;box-shadow:0 10px 24px -10px rgba(224,122,60,.55);font-family:inherit}
530	.btn-submit:hover{transform:translateY(-1px)}
531	.btn-submit:disabled{opacity:.6;cursor:not-allowed;transform:none}
532	.success-box{padding:36px 26px;text-align:center}
533	.success-icon{width:72px;height:72px;border-radius:50%;background:linear-gradient(135deg,#9ee9d3,var(--line-green));margin:0 auto 18px;display:grid;place-items:center;color:#fff;font-size:36px}
534	.success-box h3{font-family:"Noto Serif TC",serif;font-size:24px;font-weight:900;color:var(--deep-2);margin:0 0 8px}
535	.success-box>p{color:var(--ink-soft);font-size:14.5px;margin:0 0 22px;line-height:1.7}
536	.success-line-banner{background:#e6f8ee;border:1px solid #b9d6c8;border-radius:14px;padding:18px;margin-bottom:18px;text-align:left}
537	.banner-head{font-weight:900;color:var(--line-green);display:flex;align-items:center;gap:8px;font-size:15px;margin-bottom:12px}
538	.btn-line-confirm{width:100%;height:50px;background:var(--line-green);color:#fff;font-weight:900;border:0;border-radius:12px;font-size:15px;cursor:pointer;transition:.2s;display:flex;align-items:center;justify-content:center;gap:8px;font-family:inherit}
539	.btn-line-confirm:hover{background:#04a847}
540	.btn-copy-msg{display:flex;align-items:center;justify-content:center;gap:5px;margin:10px auto 0;background:transparent;border:0;color:var(--line-green);font-size:13.5px;cursor:pointer;font-weight:700;font-family:inherit}
541	.btn-copy-msg:hover{text-decoration:underline}
542	.btn-close-modal{width:100%;height:42px;background:transparent;border:0;color:var(--ink-soft);font-size:14.5px;cursor:pointer;font-weight:500;font-family:inherit}
543	.btn-close-modal:hover{color:var(--ink)}
544	@media (max-width:480px){.field-row{grid-template-columns:1fr}}
545	</style>

file.content:
.hero h1 em{
  font-style:normal;color:var(--accent-2);
  background:linear-gradient(transparent 65%,rgba(224,122,60,.32) 65%);
  padding:0 6px;
}
.hero-sub{
  font-size:22px;color:var(--ink);font-weight:700;line-height:1.55;
  margin:0 0 14px;
}
.hero-trust{
  font-size:14px;color:var(--ink-soft);letter-spacing:.06em;font-weight:600;
  padding-top:18px;margin-top:18px;border-top:1px dashed var(--line-mid);
  display:flex;flex-wrap:wrap;gap:6px 22px;align-items:center;
}
.hero-trust b{color:var(--deep-2);font-weight:900}
.hero-cta-row{
  display:flex;gap:14px;flex-wrap:wrap;margin-top:32px;
}
.btn-hero-primary{
  display:inline-flex;align-items:center;gap:10px;
  padding:18px 32px;border-radius:999px;
  background:linear-gradient(135deg,var(--accent),var(--accent-2));
  color:#fff;font-size:16px;font-weight:900;letter-spacing:.04em;
  border:0;cursor:pointer;font-family:inherit;
  box-shadow:0 16px 32px -12px rgba(224,122,60,.55);
  transition:.22s;
}
.btn-hero-primary:hover{transform:translateY(-2px);box-shadow:0 20px 38px -12px rgba(224,122,60,.7)}
.btn-hero-ghost{
  display:inline-flex;align-items:center;gap:10px;
  padding:18px 28px;border-radius:999px;
  background:transparent;border:1.5px solid var(--deep);
  color:var(--deep);font-size:15px;font-weight:700;
  cursor:pointer;font-family:inherit;transition:.22s;
}
.btn-hero-ghost:hover{background:var(--deep);color:#fff}
.hero-manifesto{
  margin-top:32px;padding:22px 26px;
  background:#fff;border:1px solid var(--accent-soft);
  border-left:4px solid var(--accent);
  border-radius:0 14px 14px 0;
  max-width:600px;
  box-shadow:0 14px 30px -16px rgba(15,42,38,.22);
}
.hero-manifesto p{
  margin:0;font-size:15.5px;color:var(--ink);
  line-height:1.85;font-style:italic;
}
.hero-manifesto p b{color:var(--accent-2);font-weight:900;font-style:normal}
.hero-manifesto span{
  display:inline-block;font-size:12px;color:var(--accent-2);
  font-weight:800;letter-spacing:.14em;margin-top:10px;
}
.hero-tagline{
  margin-top:36px;font-size:11.5px;letter-spacing:.36em;color:var(--ink-faint);font-weight:700;
}
.hero-portrait{
  position:relative;border-radius:18px;overflow:hidden;
  box-shadow:0 30px 70px -25px rgba(15,42,38,.45);
  aspect-ratio:4/5;
}
.hero-portrait img{width:100%;height:100%;object-fit:cover;object-position:center top}
.hero-portrait .badge{
  position:absolute;left:18px;bottom:18px;
  background:rgba(15,42,38,.92);color:var(--paper);
  padding:10px 18px;border-radius:10px;
  font-size:12px;font-weight:700;letter-spacing:.05em;
  backdrop-filter:blur(8px);
}
.hero-portrait .badge .name{font-family:"Noto Serif TC",serif;font-weight:900;font-size:17px;color:#fff;margin-bottom:2px}
@media (max-width:900px){
  .hero-grid{grid-template-columns:1fr;gap:36px}
  .hero h1{font-size:44px}
  .hero-sub{font-size:18px}
}

/* ===== 認知翻轉 ===== */
.shift{background:var(--paper-3);border-top:1px solid var(--line-soft);border-bottom:1px solid var(--line-soft)}
.phil-quote{
  background:#fff;border-left:5px solid var(--accent);
  padding:22px 28px;margin:28px 0 36px;
  border-radius:0 12px 12px 0;
  box-shadow:0 10px 30px -18px rgba(15,42,38,.25);
}
.phil-quote .q{font-size:16.5px;color:var(--deep-2);line-height:1.85;font-style:italic;margin:0}
.phil-quote .src{font-size:12.5px;color:var(--accent-2);font-weight:800;letter-spacing:.08em;margin-top:10px;display:block}
.compare{
  display:grid;grid-template-columns:1fr 1fr;gap:0;
  border:1px solid var(--line-soft);border-radius:14px;overflow:hidden;background:#fff;
}
.compare-col{padding:32px 28px}
.compare-col.lose{background:linear-gradient(180deg,#fcf4f0,#fff)}
.compare-col.win{background:linear-gradient(180deg,#f0f6f1,#fff);border-left:1px solid var(--line-soft)}
.compare-col h4{
  font-family:"Noto Serif TC",serif;font-weight:900;font-size:20px;margin:0 0 18px;
  display:flex;align-items:center;gap:10px;
}
.compare-col.lose h4{color:var(--red-soft)}
.compare-col.win h4{color:var(--green-good)}
.compare-col h4 .ico{width:32px;height:32px;border-radius:50%;display:grid;place-items:center;color:#fff;font-size:13px;font-weight:900;flex-shrink:0}
.compare-col.lose h4 .ico{background:var(--red-soft)}
.compare-col.win h4 .ico{background:var(--green-good)}
.compare-col ul{margin:0;padding:0;list-style:none}
.compare-col li{
  font-size:14.5px;line-height:1.75;padding:10px 0;
  border-top:1px dashed var(--line-soft);
  color:var(--ink);
}
.compare-col li:first-child{border-top:0}
@media (max-width:820px){
  .compare{grid-template-columns:1fr}
  .compare-col.win{border-left:0;border-top:1px solid var(--line-soft)}
}

/* ===== Why Coach ===== */
.why-grid{display:grid;grid-template-columns:1.2fr 1fr;gap:60px;align-items:start}
.why-stats{
  display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:24px 0 32px;
}
.why-stat{
  background:#fff;border:1px solid var(--line-soft);border-radius:12px;
  padding:18px 20px;
}
.why-stat .n{
  font-family:"Noto Serif TC",serif;font-weight:900;font-size:30px;
  color:var(--accent-2);line-height:1;
}
.why-stat .l{font-size:13px;color:var(--ink-soft);font-weight:600;margin-top:6px;letter-spacing:.04em}
.traits{display:flex;flex-direction:column;gap:18px;margin-top:8px}
.trait{
  display:flex;gap:18px;background:#fff;border:1px solid var(--line-soft);
  border-radius:14px;padding:20px 22px;
}
.trait .ch{
  flex-shrink:0;width:54px;height:54px;border-radius:14px;
  background:linear-gradient(135deg,var(--deep),var(--deep-2));
  color:var(--paper);display:grid;place-items:center;
  font-family:"Noto Serif TC",serif;font-weight:900;font-size:26px;
}
.trait h4{font-family:"Noto Serif TC",serif;font-weight:900;font-size:18px;color:var(--deep-2);margin:0 0 6px}
.trait p{margin:0;font-size:14.5px;color:var(--ink-soft);line-height:1.7}
@media (max-width:820px){
  .why-grid{grid-template-columns:1fr;gap:36px}
}

/* ===== 海餅乾正典 ===== */
.canon{background:linear-gradient(180deg,var(--deep) 0%,var(--deep-2) 100%);color:var(--paper);position:relative}
.canon::before{
  content:'';position:absolute;inset:0;
  background:
    radial-gradient(500px 280px at 100% 0%,rgba(224,122,60,.22),transparent 60%),
    radial-gradient(400px 220px at 0% 100%,rgba(181,138,79,.18),transparent 60%);
  pointer-events:none;
}
.canon .wrap{position:relative;z-index:1;max-width:880px;text-align:center}
.canon .eyebrow{color:var(--accent-soft)}
.canon .sec-title{color:#fff}
.canon .sec-title-underline{margin-left:auto;margin-right:auto}
.canon-mission{
  margin:18px auto 50px;font-family:"Noto Serif TC",serif;font-weight:900;
  font-size:30px;line-height:2;color:#fff;
}
.canon-mission em{font-style:normal;background:linear-gradient(transparent 65%,rgba(224,122,60,.42) 65%);padding:0 8px}
.canon-divider{width:80px;height:1px;background:rgba(255,255,255,.3);margin:36px auto}
.canon-beliefs-title{font-family:"Noto Serif TC",serif;font-weight:900;font-size:24px;margin-bottom:32px;letter-spacing:.06em}
.canon-beliefs{display:flex;flex-direction:column;gap:24px;text-align:left;max-width:680px;margin:0 auto}
.canon-belief{
  display:flex;gap:20px;align-items:flex-start;
  background:rgba(255,255,255,.05);
  border:1px solid rgba(255,255,255,.12);
  border-radius:16px;padding:22px 26px;
  backdrop-filter:blur(8px);
}
.canon-belief .num{
  flex-shrink:0;width:44px;height:44px;border-radius:50%;
  background:linear-gradient(135deg,var(--accent),var(--accent-2));
  color:#fff;display:grid;place-items:center;
  font-family:"Noto Serif TC",serif;font-weight:900;font-size:18px;
}
.canon-belief p{margin:0;font-size:16px;line-height:1.85;color:#fff}
.canon-belief b{color:var(--accent-soft);font-weight:900}
.canon-footnote{
  margin-top:42px;font-size:11px;letter-spacing:.24em;
  color:rgba(255,255,255,.5);font-weight:700;
}

/* ===== 六大器材 ===== */
.equipment{background:var(--paper)}
.eq-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:22px;margin-top:8px}
.eq-card{
  background:#fff;border:1px solid var(--line-soft);border-radius:18px;
  padding:28px 24px;display:flex;flex-direction:column;
  transition:.25s;position:relative;overflow:hidden;
}
.eq-card::before{
  content:'';position:absolute;left:0;top:0;width:100%;height:4px;
  background:linear-gradient(90deg,var(--accent),var(--accent-2));
  transform:scaleX(0);transform-origin:left;transition:.4s;
}
.eq-card:hover{transform:translateY(-4px);box-shadow:0 20px 40px -20px rgba(15,42,38,.25)}
.eq-card:hover::before{transform:scaleX(1)}
.eq-head{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:18px}
.eq-icon{
  width:54px;height:54px;border-radius:14px;
  background:linear-gradient(135deg,var(--deep),var(--deep-2));
  color:var(--accent-soft);display:grid;place-items:center;font-size:24px;
}
.eq-badge{
  font-size:10.5px;font-weight:800;letter-spacing:.12em;
  background:var(--accent-soft);color:var(--accent-2);
  padding:4px 10px;border-radius:6px;
}
.eq-card h3{font-family:"Noto Serif TC",serif;font-weight:900;font-size:22px;color:var(--deep-2);margin:0 0 6px}
.eq-card .obj{font-size:13.5px;color:var(--accent-2);font-weight:800;margin:0 0 14px;letter-spacing:.02em}
.eq-card .body{font-size:14px;color:var(--ink-soft);line-height:1.75;flex:1;margin:0 0 16px}
.eq-card .body b{color:var(--deep-2);font-weight:900}
.eq-card .outcome{
  padding-top:14px;border-top:1px dashed var(--line-soft);
  font-size:12.5px;color:var(--ink-soft);
}
.eq-card .outcome b{color:var(--green-good);font-weight:900}
@media (max-width:920px){.eq-grid{grid-template-columns:repeat(2,1fr)}}
@media (max-width:600px){.eq-grid{grid-template-columns:1fr}}
.eq-tagline{
  margin-top:36px;text-align:center;
  background:#fff;border:1px dashed var(--accent);border-radius:14px;
  padding:18px 24px;display:inline-flex;align-items:center;gap:12px;
}
.eq-tagline i{color:var(--accent)}
.eq-tagline .text{font-family:"Noto Serif TC",serif;font-weight:900;font-size:16.5px;color:var(--deep-2)}
.eq-tagline-row{text-align:center;margin-top:36px}

/* ===== 卡牌 / 4 步驟 ===== */
.accountable{background:linear-gradient(180deg,var(--paper-3),var(--paper-2));border-top:1px solid var(--line-soft);border-bottom:1px solid var(--line-soft)}
.accountable .wrap{max-width:1100px}
.formula{
  display:grid;grid-template-columns:repeat(4,1fr);gap:18px;margin-bottom:50px;
}
.step{
  background:#fff;border:1px solid var(--line-soft);border-radius:16px;
  padding:24px 22px;position:relative;
}
.step.consequence{background:linear-gradient(180deg,#fff7f0,#fff);border-color:var(--accent-soft)}
.step .num{
  font-family:"Noto Serif TC",serif;font-weight:900;font-size:13px;
  color:var(--accent-2);letter-spacing:.2em;margin-bottom:8px;
}
.step h4{font-family:"Noto Serif TC",serif;font-weight:900;font-size:22px;color:var(--deep-2);margin:0 0 8px}
.step p{font-size:13.5px;color:var(--ink-soft);line-height:1.7;margin:0}
@media (max-width:900px){.formula{grid-template-columns:1fr 1fr}}
@media (max-width:500px){.formula{grid-template-columns:1fr}}
.scoreboard{
  background:#fff;border:1px solid var(--line-soft);border-radius:18px;
  padding:36px;display:grid;grid-template-columns:1fr 1fr;gap:36px;
}
.scoreboard h3{font-family:"Noto Serif TC",serif;font-weight:900;font-size:26px;color:var(--deep-2);margin:0 0 14px}
.scoreboard p{font-size:14.5px;color:var(--ink-soft);line-height:1.8;margin:0 0 18px}
.scoreboard ul{margin:0;padding:0;list-style:none}
.scoreboard li{
  font-size:13.5px;color:var(--ink);
  padding:8px 0 8px 28px;position:relative;
}
.scoreboard li::before{
  content:'\f00c';font-family:'Font Awesome 6 Free';font-weight:900;
  position:absolute;left:0;top:8px;color:var(--green-good);font-size:12px;
}
.improve{
  background:linear-gradient(135deg,#fff8f0,#fcebd9);
  border:1.5px dashed var(--accent);border-radius:14px;
  padding:24px 28px;display:flex;gap:18px;align-items:flex-start;
}
.improve .ico{
  flex-shrink:0;width:48px;height:48px;border-radius:12px;
  background:linear-gradient(135deg,var(--accent),var(--accent-2));
  color:#fff;display:grid;place-items:center;font-size:22px;
}
.improve h4{font-family:"Noto Serif TC",serif;font-weight:900;font-size:20px;color:var(--deep-2);margin:0 0 6px}
.improve p{font-size:14.5px;color:var(--ink-soft);line-height:1.75;margin:0}
@media (max-width:820px){.scoreboard{grid-template-columns:1fr;padding:28px}}

/* ===== 下次見面 ===== */
.next-meet{background:var(--paper);text-align:center}
.next-meet .wrap{max-width:780px}
.next-card{
  background:linear-gradient(135deg,var(--deep),var(--deep-2));
  color:#fff;border-radius:20px;padding:48px 36px;
  box-shadow:0 30px 70px -25px rgba(15,42,38,.45);position:relative;overflow:hidden;
}
.next-card::before{
  content:'';position:absolute;top:-100px;right:-80px;width:300px;height:300px;
  border-radius:50%;background:radial-gradient(circle,rgba(224,122,60,.25),transparent 70%);
}
.next-card-inner{position:relative;z-index:1}
.next-tag{
  display:inline-block;font-size:11px;letter-spacing:.32em;font-weight:800;
  color:var(--accent-soft);background:rgba(255,255,255,.08);
  padding:6px 16px;border-radius:999px;border:1px solid rgba(255,255,255,.15);margin-bottom:18px;
}
.next-card h3{font-family:"Noto Serif TC",serif;font-weight:900;font-size:32px;color:#fff;margin:0 0 12px;line-height:1.4}
.next-card p{font-size:16px;color:rgba(255,255,255,.85);max-width:520px;margin:0 auto 28px;line-height:1.85}
.next-line-cta{
  display:inline-flex;align-items:center;gap:12px;
  background:var(--line-green);color:#fff;
  padding:16px 32px;border-radius:999px;font-weight:900;font-size:15px;
  transition:.22s;
}
.next-line-cta:hover{transform:translateY(-2px);background:#04a847}

/* ===== FAQ ===== */
.faq{background:var(--paper-3);border-top:1px solid var(--line-soft)}
.faq-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:14px}
.faq-item{
  background:#fff;border:1px solid var(--line-soft);border-radius:14px;
  padding:24px 26px;
}
.faq-item .q{
  display:flex;gap:12px;align-items:flex-start;
  font-family:"Noto Serif TC",serif;font-weight:900;font-size:17px;color:var(--deep-2);margin-bottom:10px;
}
.faq-item .q .mark{
  flex-shrink:0;width:28px;height:28px;border-radius:50%;
  background:var(--accent-soft);color:var(--accent-2);
  display:grid;place-items:center;font-size:12px;font-weight:900;
}
.faq-item .a{font-size:14.5px;color:var(--ink-soft);line-height:1.8;margin:0;padding-left:40px}
@media (max-width:820px){.faq-grid{grid-template-columns:1fr}.faq-item .a{padding-left:0}}

/* ===== 90 分鐘 CTA ===== */
.cta90{background:linear-gradient(135deg,var(--deep-2),#0a1f1c);color:#fff;position:relative;overflow:hidden}
.cta90::before{
  content:'';position:absolute;inset:0;
  background:
    radial-gradient(700px 380px at 100% 0%,rgba(224,122,60,.18),transparent 60%),
    radial-gradient(500px 280px at 0% 100%,rgba(181,138,79,.12),transparent 60%);
  pointer-events:none;
}
.cta90 .wrap{position:relative;z-index:1;max-width:880px;text-align:center}
.cta90 .eyebrow{color:var(--accent-soft)}
.cta90 h2{
  font-family:"Noto Serif TC",serif;font-weight:900;
  font-size:48px;color:#fff;margin:0 0 18px;line-height:1.3;
}
.cta90 h2 em{font-style:normal;color:var(--accent);background:linear-gradient(transparent 65%,rgba(224,122,60,.32) 65%);padding:0 6px}
.cta90-sub{font-size:19px;color:rgba(255,255,255,.85);max-width:640px;margin:0 auto 28px;line-height:1.8}
.cta90-sub b{color:var(--accent-soft);font-weight:900}
.cta90-quote{
  background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.12);
  border-radius:18px;padding:28px 32px;margin:32px auto;max-width:680px;
  text-align:left;backdrop-filter:blur(8px);
}
.cta90-quote .label{font-size:11px;letter-spacing:.32em;color:var(--accent-soft);font-weight:800;margin-bottom:12px}
.cta90-quote .q{font-size:17px;line-height:1.85;color:#fff;margin:0;font-style:italic}
.cta90-actions{display:flex;gap:14px;justify-content:center;flex-wrap:wrap;margin-top:32px}
.btn-cta90{
  display:inline-flex;align-items:center;gap:10px;
  padding:18px 36px;border-radius:999px;
  background:linear-gradient(135deg,var(--accent),var(--accent-2));
  color:#fff;font-size:16px;font-weight:900;letter-spacing:.04em;
  border:0;cursor:pointer;font-family:inherit;
  box-shadow:0 20px 40px -16px rgba(224,122,60,.6);
  transition:.22s;
}
.btn-cta90:hover{transform:translateY(-2px);box-shadow:0 24px 48px -16px rgba(224,122,60,.75)}
.btn-cta90-ghost{
  display:inline-flex;align-items:center;gap:10px;
  padding:18px 32px;border-radius:999px;
  background:transparent;border:1.5px solid rgba(255,255,255,.4);
  color:#fff;font-size:15px;font-weight:700;
  transition:.22s;
}
.btn-cta90-ghost:hover{background:rgba(255,255,255,.1)}
.cta90-promise{
  margin-top:32px;font-size:13px;letter-spacing:.18em;color:rgba(255,255,255,.5);font-weight:700;
}

/* ===== 結語 ===== */
.bookend{background:var(--paper);padding:50px 24px;text-align:center;border-top:1px solid var(--line-soft)}
.bookend .q{font-family:"Noto Serif TC",serif;font-weight:900;font-size:22px;color:var(--deep-2);margin:0 0 8px}
.bookend .src{font-size:12px;color:var(--ink-faint);letter-spacing:.12em;font-weight:700;margin-bottom:24px}
.bookend .meta{font-size:12.5px;color:var(--ink-soft);max-width:480px;margin:0 auto;line-height:1.8}

/* ===== FOOTER ===== */
.foot{background:var(--deep-2);color:rgba(250,246,238,.7);padding:32px 24px;text-align:center;font-size:12.5px;line-height:1.85}
.foot b{color:#fff;font-weight:800}
.foot .row{margin-bottom:4px}
.foot a{color:var(--accent-soft)}

/* ===== Modal (照抄 EDM 機制) ===== */
.modal{position:fixed;inset:0;z-index:200;display:none;align-items:center;justify-content:center;padding:16px}
.modal.show{display:flex}
.modal-bg{position:absolute;inset:0;background:rgba(0,0,0,.65);backdrop-filter:blur(8px)}
.modal-box{position:relative;background:#fff;border-radius:20px;width:100%;max-width:480px;overflow:hidden;box-shadow:0 28px 60px -20px rgba(0,0,0,.45);animation:modalIn .25s ease;max-height:92vh;overflow-y:auto}
@keyframes modalIn{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}
.modal-head{background:linear-gradient(135deg,var(--deep),var(--deep-2));color:#fff;padding:22px 26px;display:flex;justify-content:space-between;align-items:flex-start;gap:12px}
.modal-title{font-weight:900;font-size:21px;font-family:"Noto Serif TC",serif;line-height:1.3}
.modal-sub{font-size:13px;color:var(--accent-soft);margin-top:4px}
.modal-close{background:transparent;border:0;color:rgba(255,255,255,.75);font-size:30px;line-height:1;cursor:pointer;padding:0;flex-shrink:0}
.modal-close:hover{color:#fff}
.modal-body{padding:24px 26px 28px}
.field{display:block;margin-bottom:14px}
.field label{display:block;font-size:11.5px;font-weight:800;letter-spacing:.18em;color:var(--ink-soft);margin-bottom:6px}
.field input,.field textarea{width:100%;border:1px solid var(--line-soft);border-radius:10px;padding:11px 14px;font-size:15px;font-family:inherit;outline:none;transition:.2s;background:var(--paper);box-sizing:border-box;resize:none}
.field input:focus,.field textarea:focus{border-color:var(--accent);box-shadow:0 0 0 3px rgba(224,122,60,.18);background:#fff}
.field-row{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.field-check{display:flex;gap:10px;align-items:flex-start;margin-top:10px;font-size:13.5px;color:var(--ink-soft);line-height:1.55}
.field-check input{width:16px;height:16px;margin-top:3px;accent-color:var(--accent);flex-shrink:0}
.modal-actions{display:flex;gap:10px;margin-top:22px}
.btn-ghost{flex:1;height:48px;border:1px solid var(--line-soft);background:#fff;color:var(--ink);font-weight:700;border-radius:999px;font-size:15px;cursor:pointer;transition:.2s;font-family:inherit}
.btn-ghost:hover{background:var(--paper-2)}
.btn-submit{flex:1;height:48px;background:linear-gradient(135deg,var(--accent),var(--accent-2));color:#fff;font-weight:900;border:0;border-radius:999px;font-size:15px;cursor:pointer;transition:.2s;box-shadow:0 10px 24px -10px rgba(224,122,60,.55);font-family:inherit}
.btn-submit:hover{transform:translateY(-1px)}
.btn-submit:disabled{opacity:.6;cursor:not-allowed;transform:none}
.success-box{padding:36px 26px;text-align:center}
.success-icon{width:72px;height:72px;border-radius:50%;background:linear-gradient(135deg,#9ee9d3,var(--line-green));margin:0 auto 18px;display:grid;place-items:center;color:#fff;font-size:36px}
.success-box h3{font-family:"Noto Serif TC",serif;font-size:24px;font-weight:900;color:var(--deep-2);margin:0 0 8px}
.success-box>p{color:var(--ink-soft);font-size:14.5px;margin:0 0 22px;line-height:1.7}
.success-line-banner{background:#e6f8ee;border:1px solid #b9d6c8;border-radius:14px;padding:18px;margin-bottom:18px;text-align:left}
.banner-head{font-weight:900;color:var(--line-green);display:flex;align-items:center;gap:8px;font-size:15px;margin-bottom:12px}
.btn-line-confirm{width:100%;height:50px;background:var(--line-green);color:#fff;font-weight:900;border:0;border-radius:12px;font-size:15px;cursor:pointer;transition:.2s;display:flex;align-items:center;justify-content:center;gap:8px;font-family:inherit}
.btn-line-confirm:hover{background:#04a847}
.btn-copy-msg{display:flex;align-items:center;justify-content:center;gap:5px;margin:10px auto 0;background:transparent;border:0;color:var(--line-green);font-size:13.5px;cursor:pointer;font-weight:700;font-family:inherit}
.btn-copy-msg:hover{text-decoration:underline}
.btn-close-modal{width:100%;height:42px;background:transparent;border:0;color:var(--ink-soft);font-size:14.5px;cursor:pointer;font-weight:500;font-family:inherit}
.btn-close-modal:hover{color:var(--ink)}
@media (max-width:480px){.field-row{grid-template-columns:1fr}}
</style>

