1	<!doctype html>
2	<html lang="zh-Hant">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width,initial-scale=1">
6	<title>【風格提案】海餅乾俱樂部・商務健身房｜黑金精裝版</title>
7	<link rel="preconnect" href="https://fonts.googleapis.com">
8	<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
9	<link href="https://fonts.googleapis.com/css2?family=Noto+Sans+TC:wght@300;400;500;700;900&display=swap" rel="stylesheet">
10	<style>
11	:root{
12	  --gold:#c8a96e;
13	  --gold-light:#e3cd9c;
14	  --gold-dim:rgba(200,169,110,.35);
15	  --dark:#0a0a0a;
16	  --dark2:#131313;
